create or replace function public.recalculate_coupon_price(p_coupon_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_target integer; v_odds numeric; v_stake numeric; begin select target_legs,stake into v_target,v_stake from public.coupons where id=p_coupon_id; if not found then return; end if; select case when count(*)=v_target and bool_and(odds is not null and odds>1) then round(exp(sum(ln(odds)))::numeric,2) else null end into v_odds from public.coupon_legs where coupon_id=p_coupon_id; update public.coupons set combined_odds=v_odds,total_odds=v_odds,potential_return=case when v_stake is not null and v_odds is not null then round(v_stake*v_odds,2) else null end where id=p_coupon_id; end; $$; create or replace function public.on_coupon_leg_price_change() returns trigger language plpgsql security definer set search_path=public as $$ begin if TG_OP='DELETE' then perform public.recalculate_coupon_price(old.coupon_id); return old; else perform public.recalculate_coupon_price(new.coupon_id); return new; end if; end; $$; drop trigger if exists trg_recalculate_coupon_price on public.coupon_legs; create trigger trg_recalculate_coupon_price after insert or update of odds or delete on public.coupon_legs for each row execute function public.on_coupon_leg_price_change(); create or replace function public.sync_coupon_leg_odds_from_prediction() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.odds is distinct from old.odds then update public.coupon_legs set odds=new.odds where prediction_id=new.id; end if; return new; end; $$; drop trigger if exists trg_sync_coupon_leg_odds_from_prediction on public.predictions; create trigger trg_sync_coupon_leg_odds_from_prediction after update of odds on public.predictions for each row execute function public.sync_coupon_leg_odds_from_prediction();